function(instance, context) {
  // Generated by yarn build.
  instance.data.ready = window.TransloaditBubbleReady.then(function(api) { api.initialize(instance, context); return api; });
  instance.data.ready.catch(function(error) {
    instance.publishState('error_message', error.message);
    instance.triggerEvent('error');
  });
}
